fn dedup_sorted(values: &mut Vec<i64>) {
    if values.is_empty() {
        return;
    }

    let mut write_index: usize = 1;
    for read_index in 1..values.len() {
        if values[read_index] != values[write_index - 1] {
            values[write_index] = values[read_index];
            write_index += 1;
        }
    }

    values.truncate(write_index);
}

